package octal

import "errors"

// ParseOctal converts an octal number represented as a string to its
// decimal equivalent, computing the value directly from the powers of 8
// rather than relying on any built-in base conversion.
//
// Invalid input (an empty string, or any character outside 0-7) is
// treated as octal 0 and an error is returned.
func ParseOctal(input string) (int64, error) {
	if input == "" {
		return 0, errors.New("invalid octal input: empty string")
	}

	var result int64
	for _, r := range input {
		if r < '0' || r > '7' {
			return 0, errors.New("invalid octal input: digit must be between 0 and 7")
		}
		// Accumulate using Horner's method: each digit shifts the
		// running total up one power of 8, then adds the digit's value.
		result = result*8 + int64(r-'0')
	}
	return result, nil
}
